def _parse_hms(self, h_str, m_str, s_str, f_str):
    # Handle 24:00 as midnight
    if h_str == '24':
        if m_str != '00' or s_str != '00' or f_str != '0':
            raise ValueError('hour must be in 0..23')
        h_str = '0'
        return (0, 0, 0, 0)

    h = self._to_integer(h_str)
    m = self._to_integer(m_str)
    s = self._to_integer(s_str)
    f = self._to_integer(f_str)

    if not (0 <= h <= 23):
        raise ValueError('hour must be in 0..23')
    if not (0 <= m <= 59):
        raise ValueError('minute must be in 0..59')
    if not (0 <= s <= 59):
        raise ValueError('second must be in 0..59')

    return (h, m, s, f)

