def _parse_isotime(self, timestr):
    # Parse time string, handling 24:00 as midnight
    len_str = len(timestr)
    pos = 0
    comps = [0, 0, 0, 0]  # hour, minute, second, microsecond

    # Hour (0-24)
    if len_str - pos < 2:
        raise ValueError('Invalid hour in ISO time string')
    hour = int(timestr[pos:pos+2])
    if hour < 0 or hour > 24:
        raise ValueError('hour must be in 0..24')
    comps[0] = hour
    pos += 2

    if pos >= len_str:
        # Handle 24:00 as 00:00
        if comps[0] == 24:
            comps[0] = 0
        return comps, pos

    if timestr[pos:pos+1] == ':':
        pos += 1

    # Minute
    if len_str - pos < 2:
        raise ValueError('Invalid minute in ISO time string')
    comps[1] = int(timestr[pos:pos+2])
    if comps[1] < 0 or comps[1] > 59:
        raise ValueError('minute must be in 0..59')
    pos += 2

    if pos >= len_str:
        if comps[0] == 24:
            comps[0] = 0
        return comps, pos

    if timestr[pos:pos+1] == ':':
        pos += 1
    elif timestr[pos:pos+1] in ('.,'):
        # Fractional minutes
        frac_start = pos + 1
        frac_end = frac_start
        while frac_end < len_str and timestr[frac_end].isdigit():
            frac_end += 1
        frac_str = timestr[frac_start:frac_end]
        comps[1] = int(comps[1]) + int(frac_str.ljust(6, '0')[:6]) / 1e6
        if comps[0] == 24:
            comps[0] = 0
        return comps, frac_end
    else:
        if comps[0] == 24:
            comps[0] = 0
        return comps, pos

    # Second
    if len_str - pos < 2:
        raise ValueError('Invalid second in ISO time string')
    comps[2] = int(timestr[pos:pos+2])
    if comps[2] < 0 or comps[2] > 59:
        raise ValueError('second must be in 0..59')
    pos += 2

    if pos < len_str and timestr[pos:pos+1] in ('.,'):
        frac_start = pos + 1
        frac_end = frac_start
        while frac_end < len_str and timestr[frac_end].isdigit():
            frac_end += 1
        frac_str = timestr[frac_start:frac_end]
        comps[3] = int(frac_str.ljust(6, '0')[:6])
        pos = frac_end

    # Handle 24:00 as 00:00
    if comps[0] == 24:
        if comps[1] != 0 or comps[2] != 0 or comps[3] != 0:
            raise ValueError('24:00:00 is only valid with 00 minutes and seconds')
        comps[0] = 0

    return comps, pos

