def _parse(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False, fuzzy_with_tokens=False):
    """
    Private parse method. Parses the input string into a datetime object.
    """
    if dayfirst is None:
        dayfirst = self.dayfirst
    if yearfirst is None:
        yearfirst = self.yearfirst

    res = self._result()
    skipped_tokens = []
    naive = True

    try:
        ret = self._timelex.split(timestr)
    except AttributeError:
        ret = _timelex(timestr)

    for offset, token in enumerate(ret):
        lowtoken = token.lower()
        if not token:
            continue

        parsed = False
        for pFunc in self._parser_funcs:
            try:
                res, parsed = pFunc(res, token, lowtoken, offset, ret)
                if parsed:
                    break
            except ValueError:
                continue

        if not parsed:
            skipped_tokens.append(token)

        if res.hour is not None:
            # Handle ISO 24:00 special case - convert to 00:00 of next day
            if res.hour == 24:
                if res.minute != 0 or res.second != 0 or res.microsecond != 0:
                    raise ValueError("hour must be in 0..23")
                res.hour = 0
                res.day += 1

    if fuzzy_with_tokens:
        return res, skipped_tokens
    elif fuzzy:
        return res
    else:
        return res

def _parse_hms(self, h, m, s, microsegundos):
    """
    Parse hour, minute, second and microseconds, handling 24:00 case.
    """
    # Handle ISO 24:00 - represents midnight (00:00 of next day)
    if h == 24:
        if m != 0 or s != 0 or microsegundos != 0:
            raise ValueError("hour must be in 0..23 when hour is 24 and other time components are non-zero")
        h = 0
        return h, m, s, microgroundos, True  # True indicates day should be incremented

    return h, m, s, microgroundos, False

