def _parse_isotime(self, timestr):
    # This is a private method that parses the time portion of an ISO string.
    # Components are: (hour, minute, second, microsecond)

    len_str = len(timestr)
    pos = 0
    comps = []
    for i in range(0, 3):
        if i == 0:
            # Hour: Allow 24 for midnight
            ret = self._parse_isodate_common(timestr[pos:], i == 2)
        else:
            ret = self._parse_isodate_common(timestr[pos:], i == 2)

    # Hour
    hour_match = re.match(r'(\d{1,2})', timestr[pos:])
    if hour_match:
        hour = int(hour_match.group(1))
        if hour > 24:
            raise ValueError('hour must be in 0..24')
        comps.append(hour)
        pos += len(hour_match.group(0))
    else:
        raise ValueError('hour not found')

    # Optional minute
    if pos < len_str and timestr[pos:pos+1:] in (b':', b''):
        if timestr[pos:pos+1] == b':':
            pos += 1
        minute_match = re.match(r'(\d{1,2})', timestr[pos:])
        if minute_match:
            minute = int(minute_match.group(1))
            if minute > 59:
                raise ValueError('minute must be in 0..59')
            comps.append(minute)
            pos += len(minute_match.group(0))

    # Optional second
    if pos < len_str and timestr[pos:pos+1] in (b':', b''):
        if timestr[pos:pos+1] == b':':
            pos += 1
        second_match = re.match(r'(\d{1,2})', timestr[pos:])
        if second_match:
            second = int(second_match.group(1))
            if second > 59:
                raise ValueError('second must be in 0..59')
            comps.append(second)
            pos += len(second_match.group(0))

    # Optional fractional seconds
    if pos < len_str and timestr[pos:pos+1] in (b'.', b','):
        pos += 1
        frac_match = re.match(r'(\d+)', timestr[pos:])
        if frac_match:
            frac_str = frac_match.group(1)
            # Pad or truncate to 6 digits for microseconds
            frac = int(frac_str.ljust(6, b'0')[:6])
            comps.append(frac)
            pos += len(frac_str)

    # Pad comps to have at least (hour, minute, second, microsecond)
    while len(comps) < 4:
        comps.append(0)

    return comps[:4]

