def _parse_isotime(self, timestr):
    # This is adapted from the `parse_time` method from the datetime
    # library, which we could not use because we need to support leap
    # seconds.
    len_str = len(timestr)
    pos = 0
    comps = {}

    for i, key in enumerate(('hour', 'minute', 'second')):
        if pos >= len_str:
            break

        if i == 0:
            _int_re = re.compile(br'(\d{1,2})')
        else:
            _int_re = re.compile(br'(\d{2})')

        m = _int_re.match(timestr[pos:])
        if not m:
            break

        comps[key] = int(m.group(1))
        pos += len(m.group(0))

        if i < 2:
            if pos < len_str and timestr[pos:pos + 1:] != b':':
                break
            elif pos < len_str:
                pos += 1

    # Handle fractions
    frac = None
    if pos < len_str and timestr[pos:pos + 1] in (b'.', b','):
        frac_str = timestr[pos + 1:]
        m = re.match(br'(\d+)', frac_str)
        if m:
            frac_len = len(m.group(1))
            frac = int(m.group(1).ljust(6, b'0'))
            pos += frac_len + 1

    comps['microsecond'] = frac or 0

    # Handle timezone
    tzstr = timestr[pos:]
    if tzstr:
        tzdata = self._parse_tzstr(tzstr)
    else:
        tzdata = None

    out = [comps.get('hour', 0),
           comps.get('minute', 0),
           comps.get('second', 0),
           comps['microsecond']]

    if tzdata is not None:
        out.append(tzdata)

    return out

