def parse_isotime(self, timestr):
    components, pos = self._parse_isotime(timestr)
    if pos < len(timestr):
        raise ValueError('String contains unknown ISO ' +
                         'components: {}'.format(timestr))
    hour, minute, second, microsecond = components
    if hour == 24:
        if minute != 0 or second != 0 or microsecond != 0:
            raise ValueError('Hour is 24, but minute, second, '
                           'or microsecond are nonzero')
        return (0, 0, 0, 0), True
    return components, False

