def isoparse(self, dt_str, **kwargs):
    datepart, timepart = self._split_isodate(dt_str)

    if datepart:
        date_obj = self.parse_isodate(datepart)
    else:
        date_obj = None

    if timepart:
        time_components, rollover = self.parse_isotime(timepart)
        if rollover:
            date_obj = date_obj + timedelta(days=1)
            time_obj = time(*time_components)
        else:
            time_obj = time(*time_components)
    else:
        time_obj = None

    if date_obj and time_obj:
        return datetime.combine(date_obj, time_obj)
    elif date_obj:
        return datetime.combine(date_obj, time())
    else:
        return datetime.combine(date.today(), time_obj)
